"use client"

import { cn } from "@/lib/utils"
import { TrendingUp, TrendingDown } from "lucide-react"

interface StatCardProps {
  label: string
  value: string
  change?: string
  changeType?: "positive" | "negative" | "neutral"
  variant?: "cash" | "revenue" | "expense" | "profit"
}

const variantStyles = {
  cash: "before:bg-primary",
  revenue: "before:bg-chart-1",
  expense: "before:bg-destructive",
  profit: "before:bg-accent",
}

export function StatCard({
  label,
  value,
  change,
  changeType = "neutral",
  variant = "cash",
}: StatCardProps) {
  return (
    <div
      className={cn(
        "bg-card p-6 rounded-lg border border-border shadow-sm relative overflow-hidden transition-all hover:-translate-y-0.5 hover:shadow-md",
        "before:absolute before:top-0 before:left-0 before:w-1 before:h-full",
        variantStyles[variant]
      )}
    >
      <p className="text-xs uppercase tracking-wide text-muted-foreground font-semibold mb-3">
        {label}
      </p>
      <p className="text-2xl font-serif font-semibold text-foreground mb-2 tabular-nums">
        {value}
      </p>
      {change && (
        <div
          className={cn(
            "flex items-center gap-1.5 text-sm",
            changeType === "positive" && "text-chart-1",
            changeType === "negative" && "text-destructive",
            changeType === "neutral" && "text-muted-foreground"
          )}
        >
          {changeType === "positive" && <TrendingUp className="h-4 w-4" />}
          {changeType === "negative" && <TrendingDown className="h-4 w-4" />}
          <span>{change}</span>
        </div>
      )}
    </div>
  )
}
